function pageUpdated(){
	$("#marker").show();
	if(currMode == 'simple') return;
	if(currMode == 'memorize'){
		var page = currPage;
		drawHilites(page , true);
		if( page % 2 ){
			drawHilites(page+1 , true);	
		}
		else{
			drawHilites(page-1 , true);
		}			
		memorize_hiliteAya(memorize_currAya);

		return;
	}
	$(".fld_goto_page").val(currPage);
	imgAfterLoad( currPage );
	setTimeout(function(){
		manOverlays();
	} , 200);
}
function beforeUpdatePage(){
	removeOverlays();
	tabsMan.closeTabs();
	hideWidget();
	stopPlayer();
	$("#marker").hide();
}
function loadPage( n  ) {
    if(n == 'laheq') {
        loadPage(currPage + 1);
        return;
    } else if(n == 'sabeq') {
        loadPage(currPage - 1);
        return;
    }
    if(pageBusy){
    	return;
    }

    pageBusy = true;

    /*-------------------*/
    beforeUpdatePage();
    /*-------------------*/
    var n = Number(n);
    if( Math.abs(currPage-n) <= 1) {

        if(n > currPage) { // laheq
            if(currPage % 2) {
                currPage = n;
                pageBusy = false;
                pageUpdated();
                return;
            }
        } else if(n < currPage){
            if(currPage % 2 == 0) {
                currPage = n;
                pageBusy = false;
                pageUpdated();
                return;
            }
        }
        else{
            pageBusy = false;
            pageUpdated();
            return;
        }
    }

    if(n > currPage) {
        $("#book").booklet('prev');
    } else {
        $("#book").booklet('next');
    }

	currPage = n;

}

function setCurrAya(sura , aya){
	var sura = Number(sura);
	var aya  = Number(aya);
	if(isNaN(sura) || sura < 1) sura = 1;
	if(sura > 114) sura = 114;

	if( isNaN(aya) || (aya > QuranData.Sura[ sura ][1]) ) aya = 1;

	if(currAya && (currAya == sura+'_'+aya)) return;

	currAya = sura+'_'+aya;

	$.bbq.pushState('aya='+sura+'_'+aya);


	//$.get(url_interface+'&do=current&sub=aya&state='+currAya);
	setCookie('pc_curr_aya' , currAya , 365 , '/' , '' ,'');
}
function loadAya(sura, aya){

	loadPage( suraSafha(sura, aya) );
	setCurrAya(sura, aya);
}

