function startRepeat(){
	repeat['begin_aya'] = $("#repeat_sel_begin_sura").val() + '_' + $("#repeat_sel_begin_aya").val();
	repeat['end_aya']   = $("#repeat_sel_end_sura").val() + '_' +   $("#repeat_sel_end_aya").val();
