	repeat['for_aya']   = Number($("#repeat_for_aya").val()) || 0;
	repeat['for_all']   = Number($("#repeat_for_all").val()) || 0;

	setCurrAya(repeat['begin_aya'].split('_')[0] , repeat['begin_aya'].split('_')[1]);
	playAya();
	set_globalPlay(1);

	in_repeat_mode = true;

	$("#repeat_widg").find("input,select,button").each(function(){
		this.disabled = 1;
	});
