    SG.Naver = (function ($) {
        var sets = { 
            defaultSet: function (id) {
                return new Naver('#' + id, {
                    scrollX: false,
                    scrollY: true,

                    snap: false,
                    momentum: true,
                    momentumY: true,

                    useTransition: useTransition(),
                    preventDefault: false
                });
            },
            horSet: function(id){
                return new Naver('#' + id, {
                    scrollX: true,
                    scrollY: false,
                    snap: false,
                    momentum: true,
                    momentumX: true,
                    useTransition: useTransition(),
                    preventDefault: false
                });
            }
        }
        var navs = {};
        var actives = {};
        return {
            attach: function (id, act, delay) {
                if (!navs[id]) {
                    navs[id] = (typeof act == 'string') ? sets[act](id) : act();
                }
            },
            refresh: function (id) {
                if (!navs[id]) return;
                navs[id].refresh();
            },
            setOpt: function(id, opt, val){
                if (!navs[id]) return;
                navs[id].options[opt] = val;
            },
            refreshActives: function () {
                for (var id in actives) {
                    if (navs[id])
                        navs[id].refresh();
                }
            },
            activate: function (id, dontRefresh) {
                if (!navs[id]) return;
                actives[id] = true;
                if (dontRefresh) return;

                if (navs[id]) navs[id].refresh(); // @Enhancement, dont refresh unless needed

            },
            deactivate: function (id) {
                if (!navs[id]) return;

                actives[id] = undefined;
            },
            get: function (id) {
                return navs[id];
            }
        }
    })($);

