        var toggle = function (t) {
            var vas = false;
            if (viewAltSub) {
                vas = viewAltSub;
            }
            viewAltSub = false;
            if ((t > 0) && vas) {
                showSub(vas);
            }
            else if ((t < 0) && activeSub) {
                hideSub(activeSub);
            }
            else {
                if (t > 0 && visible()) return;
                if (t < 0 && !visible()) return;
                (visible()) ? hide() : show();
            }
        }
        var visible = function () {
            return (state) ? true : false;
        }

