                }
            }

        }
        var isInited = function (id) {
            return ($.inArray(id, inits) != -1);
        }
        return {
            toggle: toggle,
            setAltSub: setAltSub,
            hideActiveSub: hideActiveSub,
            setAction: setAction,
            setIniter: setIniter,
