function sortAyat(o) {
    var sorted = {}, key, a = [];

    for (key in o) {
        if (o.hasOwnProperty(key)) {
            a.push(key);
        }
    }

    a.sort(function (a, b) {
        if (Number(a.split('_')[0]) < Number(b.split('_')[0])) return -1;
        if (Number(a.split('_')[0]) > Number(b.split('_')[0])) return 1;
        if (Number(a.split('_')[1]) < Number(b.split('_')[1])) return -1;
        return 1;
    });

    for (key = 0; key < a.length; key++) {
        sorted[a[key]] = o[a[key]];
    }
    return sorted;

}
